/bin/bash -lc "mkdir -p deliverables && cat > deliverables/inspect.py <<'PY'
import FreeCAD as App
import Part
from pathlib import Path
doc=App.openDocument(str(Path('inputs/broken_mount.FCStd').resolve()))
for o in doc.Objects:
 print('\\nOBJECT',o.Name,o.TypeId,'parents',[p.Name for p in o.InList])
 for p in ['Group','LinkedObject','LinkTransform','Placement','LinkPlacement']:
  if p in o.PropertiesList: print(p,str(getattr(o,p)))
 if hasattr(o,'getGlobalPlacement'): print('global',o.getGlobalPlacement())
 if hasattr(o,'Shape'): print('shape',o.Shape.ShapeType,'solids',len(o.Shape.Solids),'vol',o.Shape.Volume,'bbox',o.Shape.BoundBox,'placement',o.Shape.Placement)
PY
python3 freecad_python.py deliverables/inspect.py"

